// Deno is only available in Supabase Edge Functions / Deno Deploy runtime.
// This declaration keeps tsc happy; at runtime in Node/browser the Deno
// namespace won't exist and the code falls through to the options path.
declare const Deno: { env: { get(key: string): string | undefined; toObject(): Record<string, string> } } | undefined;

export interface ConnectorConnection {
  accessToken: string;
  connectionConfig: Record<string, unknown>;
}

export interface ConnectorsOptions {
  /**
   * Pre-configured connector tokens keyed by integration type (e.g. 'outlook', 'slackbot').
   * Only use this for testing; in deployed Edge Functions, tokens come from Supabase secrets
   * (STATICBOT_CONNECTOR_<type>). Lower priority than env vars.
   */
  [integrationType: string]: string | ConnectorConnection | undefined;
}

/**
 * Creates the Connectors module matching `base44.asServiceRole.connectors.*`.
 *
 * Token resolution order:
 * 1. Deno.env.get('STATICBOT_CONNECTOR_{type}') — set by Supabase secrets (preview or production)
 * 2. options[integrationType] — for local testing / direct injection
 * 3. Throw with a descriptive error listing which connectors are configured
 */
export function makeConnectors(opts: ConnectorsOptions | undefined) {
  function resolveToken(integrationType: string): ConnectorConnection {
    // 1. Supabase Edge Function secret (preview bridge or customer-provided).
    try {
      const envKey = `STATICBOT_CONNECTOR_${integrationType}`;
      if (typeof Deno !== 'undefined' && Deno.env) {
        const raw = Deno.env.get(envKey);
        if (raw) {
          try {
            const parsed = JSON.parse(raw) as ConnectorConnection;
            if (parsed.accessToken) return parsed;
          } catch {
            return { accessToken: raw, connectionConfig: {} };
          }
        }
      }
    } catch {
      // Deno namespace not available — not running in an Edge Function. Fall through.
    }

    // 2. Options fallback (testing / local dev).
    if (opts) {
      const val = opts[integrationType];
      if (typeof val === 'string') {
        return { accessToken: val, connectionConfig: {} };
      }
      if (val && typeof val === 'object' && 'accessToken' in val) {
        return val as ConnectorConnection;
      }
    }

    // 3. Nothing found — surface what IS configured.
    const available: string[] = [];
    try {
      if (typeof Deno !== 'undefined' && Deno.env) {
        for (const [k] of Object.entries(Deno.env.toObject())) {
          if (k.startsWith('STATICBOT_CONNECTOR_')) {
            available.push(k.slice('STATICBOT_CONNECTOR_'.length));
          }
        }
      }
    } catch {
      // Can't enumerate env — skip.
    }
    if (opts) {
      for (const k of Object.keys(opts)) {
        if (!available.includes(k)) available.push(k);
      }
    }

    const hint =
      available.length > 0
        ? ` Available connectors: ${available.join(', ')}.`
        : ' No connector tokens are configured.';
    throw new Error(
      `Connector '${integrationType}' not found. Set a Supabase function secret ` +
        `named STATICBOT_CONNECTOR_${integrationType} with the OAuth token JSON ` +
        `(or pass the token via createClient({ connectors: { ${integrationType}: "..." } })).` +
        hint,
    );
  }

  return {
    /**
     * Retrieve OAuth credentials for a connector integration type.
     * Returns { accessToken, connectionConfig }. Matches the Base44 SDK's
     * `base44.asServiceRole.connectors.getConnection(integrationType)`.
     */
    async getConnection(integrationType: string): Promise<ConnectorConnection> {
      if (!integrationType || typeof integrationType !== 'string') {
        throw new Error('Integration type is required and must be a string');
      }
      return resolveToken(integrationType);
    },

    /**
     * Deprecated alias for getConnection — returns only the accessToken string.
     * @deprecated Use getConnection(integrationType) instead.
     */
    async getAccessToken(integrationType: string): Promise<string> {
      if (!integrationType || typeof integrationType !== 'string') {
        throw new Error('Integration type is required and must be a string');
      }
      return resolveToken(integrationType).accessToken;
    },
  };
}
